import type { Department, JobTitle } from '../employee.constants';
import {
  CountryCodeField,
  DepartmentField,
  EmailField,
  EndDateField,
  FirstNameField,
  JobTitleField,
  LastNameField,
  StartDateField,
} from './employee-fields';

/** The employee code is generated by the server and is not accepted here. */
export class CreateEmployeeDto {
  @FirstNameField()
  firstName!: string;

  @LastNameField()
  lastName?: string | null;

  @EmailField()
  email?: string | null;

  @CountryCodeField()
  countryCode!: string;

  @DepartmentField()
  department!: Department;

  @JobTitleField()
  jobTitle!: JobTitle;

  /** Hire date in YYYY-MM-DD format. */
  @StartDateField()
  startDate!: string;

  /** Termination date in YYYY-MM-DD format; omit for active employees. */
  @EndDateField()
  endDate?: string | null;
}
